regions.script:
script.openScriptList()[eventMarked(24),!eventMarked(25)];
player.moveTo(110,140,false);
script.break();
player.setDirection(left);
player.showFace(duihua);
dialogBox.showPlayerPortrait();
dialogBox.setType(type_left);
dialogBox.setText(/重楼/：你是渔夫么？);
dialogBox.showDialog();
script.break();
player.hideFace();
dialogBox.hidePortrait();
script.break();
npc.showFace(17,duihua);
npc.setDirection(17,right);
dialogBox.setText(/渔夫哈青/：对不起，我不出海！);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
partner.out(0,2,110,165,4);
script.break();
npc.setDirection(2,left);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：渔夫大哥，我们要去仙灵岛去救人。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
dialogBox.hidePortrait();
script.break();
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：救人？！哼，别骗人了，现在哪有好人。我的妻子都……);
dialogBox.showDialog();
script.break();
npc.moveTo(2,95,165,4);
script.break();
npc.hideFace(17);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：你的妻子？难道渔夫大哥你有什么难处。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
script.wait(500);
script.break();
dialogBox.hidePortrait();
script.break();
system.showAsideInfo(渔夫注视月瑶,1500);
script.wait(1500);
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：（看来她没有骗我）。);
dialogBox.showDialog();
script.break();
dialogBox.setText(/渔夫哈青/：实不相瞒，实不相瞒，我的妻子媛媛被妖怪抢跑了……);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：什么妖怪。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
dialogBox.hidePortrait();
script.break();
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：昨天我和妻子去雾林游玩，突然出现了妖怪袭击我们，我的妻子推开了我，但自己却被妖怪抓到了，妻子抓住了妖怪的手臂让我快跑，我这才幸免。);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：真是可恶的妖怪，渔夫大哥你放心，我们一定帮你找回你妻子。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
dialogBox.hidePortrait();
script.break();
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：那就多谢两位少侠了，如果能帮我找回我的妻子我定当送两位去仙灵岛。);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：重楼大哥我们这就去救渔夫大哥的妻子。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
dialogBox.hidePortrait();
script.break();
partner.in(0,2,6);
script.break();
player.moveTo(player.x+30,-1,false);
script.break();
system.showAsideInfo(救渔夫妻子,1500);
script.wait(1500);
player.firstTask(救渔夫妻子);
game.markEvent(25);
world.change(yw_yhsj.map,yw.bin,yewai.ant,yewai.bin,378,74,down);
script.closeScriptList();


script.openScriptList()[eventMarked(2502),!eventMarked(2503)];
npc.setDirection(17,right);
player.moveTo(110,140,false);
script.break();
player.setDirection(left);
npc.setPosition(15,110,140);
npc.moveTo(15,90,140,6);
script.break();
npc.setDirection(15,left);
partner.out(0,2,110,165,4);
script.break();
npc.setDirection(2,left);
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：媛媛……);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
npc.showFace(15,duihua);
dialogBox.setText(/媛媛/：哈青……);
dialogBox.showDialog();
script.break();
npc.hideFace(15);
system.showAsideInfo(两人对视,1500);
script.wait(1500);
npc.setDirection(15,right);
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：多谢两位少侠，我这就出海送你们去仙灵岛。);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
npc.showFace(2,duihua);
dialogBox.setType(type_right);
dialogBox.showNpcPortrait(2);
dialogBox.setText(/月瑶/：那就多谢哈青大哥了。);
dialogBox.showDialog();
script.break();
npc.hideFace(2);
dialogBox.hidePortrait();
script.break();
npc.setDirection(15,left);
npc.showFace(15,duihua);
dialogBox.setText(/媛媛/：哈青……);
dialogBox.showDialog();
script.break();
dialogBox.setText(/媛媛/：哈青……早去早回！);
dialogBox.showDialog();
script.break();
npc.hideFace(15);
npc.showFace(17,duihua);
dialogBox.setText(/渔夫哈青/：嗯。);
dialogBox.showDialog();
script.break();
npc.hideFace(17);
game.markEvent(2503);
world.change(yw_yhsj.map,yw.bin,yewai.ant,yewai.bin,402,285,right);
script.closeScriptList();
